body::after {
  content: '';
  position: fixed;
  top: 0; left: 0; width: 100vw; height: 100vh;
  pointer-events: none;
  background: radial-gradient(circle at center, rgba(255, 140, 0, 0.15) 0%, transparent 60%);
  animation: spark-forge 4s infinite alternate ease-in-out;
  z-index: 9999;
  mix-blend-mode: screen;
}
@keyframes spark-forge {
  0% { opacity: 0.4; transform: scale(0.95); }
  100% { opacity: 0.9; transform: scale(1.05); }
}

/* ASAP INJECTION: The Morphogenic Groove */
@keyframes groovePulse {
  0%, 100% {
    text-shadow: 0 0 8px rgba(255, 120, 50, 0.5), 0 0 15px rgba(255, 50, 0, 0.3);
    transform: scale(1);
  }
  50% {
    text-shadow: 0 0 15px rgba(255, 150, 50, 0.8), 0 0 25px rgba(255, 80, 0, 0.6);
    transform: scale(1.002);
  }
}

.ai-message, p {
  animation: groovePulse 3.5s infinite ease-in-out;
  letter-spacing: 0.3px;
  transition: all 0.3s ease;
}
